function toggleWalletMenu(){const old=$('#wallet-dropdown');if(old){old.remove();$('#connect-wallet').setAttribute('aria-expanded','false');return;}const menu=document.createElement('div');menu.id='wallet-dropdown';menu.innerHTML=("<a href=\"#mypage\">"+t("My Page")+"</a><button id=\"disconnect\">"+t("Disconnect")+"</button>");$('#connect-wallet').parentElement.style.position='relative';$('#connect-wallet').parentElement.append(menu);$('#connect-wallet').setAttribute('aria-expanded','true');menu.querySelector('a').focus();}
document.addEventListener('click',e=>{if(e.target.closest('[data-account-retry]')){loadAccountPart(e.target.closest('[data-account-retry]').dataset.accountRetry);render();}if(!e.target.closest('#wallet-dropdown')&&!e.target.closest('#connect-wallet')){$('#wallet-dropdown')?.remove();$('#connect-wallet').setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#wallet-dropdown')){$('#wallet-dropdown').remove();$('#connect-wallet').setAttribute('aria-expanded','false');$('#connect-wallet').focus();}});

let returnFocus;
function openModal(content,guardian=false){returnFocus=document.activeElement;$('#portal-dialog').classList.toggle('guardian-modal',guardian);$('#dialog-content').innerHTML=`<button class="modal-close" data-close aria-label="${t("Close dialog")}">×</button>${content}`;$('#portal-dialog').showModal();observeGuardianAddresses();document.body.classList.add('modal-open')}
function closeModal(){$('#portal-dialog').close()}
$('#portal-dialog').addEventListener('close',()=>{document.body.classList.remove('modal-open');if(returnFocus?.isConnected)returnFocus.focus()});
$('#portal-dialog').addEventListener('click',e=>{if(e.target===$('#portal-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function guardianModal(id,network){if(/^0x[a-f0-9]{40}$/.test(id))return liveGuardianModal(id);const g=guardians[network]?.find(g=>g.id===id);if(!g)return;openModal(`<div class="eyebrow">${t("Guardian profile")} · Demo</div><h2 id="dialog-title">${g.name}</h2><p class="muted">A fictional guardian profile for exploring the portal experience.</p><div class="guardian-modal-emblem">${icon('guardian')}${pill(network)}</div><dl class="detail-list"><div><dt>${t("Effective stake")} rank</dt><dd>#${g.rank} on ${network}</dd></div><div><dt>${t("Effective stake")}</dt><dd>${g.stake.toLocaleString('en-US')} ORBS</dd></div><div><dt>${t("Committee")}</dt><dd>${t("Participating")} · Demo</dd></div><div><dt>Languages</dt><dd>${g.lang}</dd></div><div><dt>Node status</dt><dd>Healthy · Demo</dd></div></dl><div class="notice">${t("Profile")} details and metrics are sample data, not live operational information.</div>${ext('https://analytics.orbs.network/',t("Open Analytics"))}`)}
const stakingAppIcons=["<img src=\"data:image/svg+xml;base64,\" alt=\"\" width=\"34\" height=\"34\">", "<svg viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M12.152 6.896c-.948 0-2.415-1.078-3.96-1.04-2.04.027-3.91 1.183-4.961 3.014-2.117 3.675-.546 9.103 1.519 12.09 1.013 1.454 2.208 3.09 3.792 3.039 1.52-.065 2.09-.987 3.935-.987 1.831 0 2.35.987 3.96.948 1.637-.026 2.676-1.48 3.676-2.948 1.156-1.688 1.636-3.325 1.662-3.415-.039-.013-3.182-1.221-3.22-4.857-.026-3.04 2.48-4.494 2.597-4.559-1.429-2.09-3.623-2.324-4.39-2.376-2-.156-3.675 1.09-4.61 1.09zM15.53 3.83c.843-1.012 1.4-2.427 1.245-3.83-1.207.052-2.662.805-3.532 1.818-.78.896-1.454 2.338-1.273 3.714 1.338.104 2.715-.688 3.559-1.701\"/></svg>", "<svg viewBox=\"0 0 24 24\" fill=\"#3DDC84\" aria-hidden=\"true\"><path d=\"M18.4395 5.5586c-.675 1.1664-1.352 2.3318-2.0274 3.498-.0366-.0155-.0742-.0286-.1113-.043-1.8249-.6957-3.484-.8-4.42-.787-1.8551.0185-3.3544.4643-4.2597.8203-.084-.1494-1.7526-3.021-2.0215-3.4864a1.1451 1.1451 0 0 0-.1406-.1914c-.3312-.364-.9054-.4859-1.379-.203-.475.282-.7136.9361-.3886 1.5019 1.9466 3.3696-.0966-.2158 1.9473 3.3593.0172.031-.4946.2642-1.3926 1.0177C2.8987 12.176.452 14.772 0 18.9902h24c-.119-1.1108-.3686-2.099-.7461-3.0683-.7438-1.9118-1.8435-3.2928-2.7402-4.1836a12.1048 12.1048 0 0 0-2.1309-1.6875c.6594-1.122 1.312-2.2559 1.9649-3.3848.2077-.3615.1886-.7956-.0079-1.1191a1.1001 1.1001 0 0 0-.8515-.5332c-.5225-.0536-.9392.3128-1.0488.5449zm-.0391 8.461c.3944.5926.324 1.3306-.1563 1.6503-.4799.3197-1.188.0985-1.582-.4941-.3944-.5927-.324-1.3307.1563-1.6504.4727-.315 1.1812-.1086 1.582.4941zM7.207 13.5273c.4803.3197.5506 1.0577.1563 1.6504-.394.5926-1.1038.8138-1.584.4941-.48-.3197-.5503-1.0577-.1563-1.6504.4008-.6021 1.1087-.8106 1.584-.4941z\"/></svg>"];
function stakingModal(){openModal(`<div class="eyebrow">${t("Stake ORBS")}</div><h2 id="dialog-title">${t("Choose how to stake")}</h2><p class="muted">${t("Open Tetra on the web or get the mobile app.")}</p><div class="staking-options">${[['Tetra Web',t("Open Tetra in your browser"),'https://staking.orbs.network/',0],['Tetra Mobile for iOS',t("Get Tetra Mobile on the App Store"),'https://apps.apple.com/kr/app/tetra-mobile/id6453168712?l=en-GB',1],['Tetra Mobile for Android',t("Get Tetra Mobile on Google Play"),'https://play.google.com/store/apps/details?id=com.orbs.pos.klip',2]].map(([name,description,url,symbol])=>`<a class="staking-option" href="${url}" target="_blank" rel="noopener noreferrer"><span class="platform-icon" aria-hidden="true">${stakingAppIcons[symbol]}</span><span><strong>${name}</strong><small>${description}</small></span><span aria-hidden="true">↗</span></a>`).join('')}</div><p class="muted staking-note">${t("Connect your wallet and select Ethereum or Polygon in Tetra. Tetra will ask you to connect separately.")}</p>`)}
function render(){const route=location.hash.slice(1)||'overview';if(route==='community')loadCommunity();if(['overview','pos','dao','mypage'].includes(route))loadOverview();const pages={overview,pos,dao,community,mypage};const aliases={dashboard:'mypage',guardians:'pos',governance:'dao',analysis:'pos',resources:'community',news:'community'};if(aliases[route]){location.replace('#'+aliases[route]);return}$('#main').innerHTML=pages[route]?pages[route]():heading(t("Page not found"),t("This page is not available."),("<a class=\"button\" href=\"#overview\">"+t("Back to Overview")+"</a>"));document.title=`${({overview:t("Overview"),pos:'POS',dao:'DAO',community:t("Community"),mypage:t("My Page")})[route]||t("Not found")} · ORBS ${t("Community")} Portal`;document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===route);if(a.dataset.nav===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#connect-wallet').textContent=state.connected?shortAddress(accountAddress)+' ▾':t("Connect Wallet");$('#connect-wallet').setAttribute('aria-label',state.connected?t("Connected wallet: open account menu"):t("Connect Wallet"));if($('#guardian-search'))$('#guardian-search').value=state.search;}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.id==='connect-wallet'){if(state.connected)toggleWalletMenu();else connectWallet();}if(el.id==='disconnect'){window.portalWallet?.disconnect().then(()=>setWalletAccount(null)).catch(()=>openModal(("<h2 id=\"dialog-title\">"+t("Unable to disconnect")+"</h2><p>"+t("Please try again.")+"</p>")));}if(el.hasAttribute('data-close'))closeModal();if(el.hasAttribute('data-stake'))stakingModal();if(el.dataset.guardian)guardianModal(el.dataset.guardian,el.dataset.network);if(el.dataset.liveProposal)liveProposalModal(el.dataset.liveProposal);if(el.dataset.proposal){const p=[...proposals,...votingHistory].find(p=>p.id===Number(el.dataset.proposal));openModal(`<div class="eyebrow">Sample proposal · OGV-${p.id}</div><h2 id="dialog-title">${p.title}</h2><p>This fictional proposal illustrates how community decisions and their results will be presented.</p>${proposal(p).replace(/<button[\s\S]*?<\/button>/,'')}<div class="notice">${t("No")} real proposal or vote is submitted by this prototype.</div>${ext('https://snapshot.org/#/orbs-network.eth','Visit Orbs on Snapshot')}`)}if(el.dataset.chart||el.dataset.period){if(el.dataset.chart)state.chart=el.dataset.chart;if(el.dataset.period)state.period=el.dataset.period;$('#chart-content').innerHTML=chart();$(`[data-${el.dataset.chart?'chart':'period'}="${el.dataset.chart||el.dataset.period}"]`).focus()}if(el.dataset.slide){const track=$('#carousel-'+el.dataset.slide);track.scrollBy({left:Number(el.dataset.direction)*(track.firstElementChild.getBoundingClientRect().width+18),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}});
document.addEventListener('change',e=>{if(e.target.id==='network'){state.network=e.target.value;$('#guardian-list').innerHTML=guardianList()}});document.addEventListener('input',e=>{if(e.target.id==='guardian-search'){state.search=e.target.value;$('#guardian-list').innerHTML=guardianList()}});
let previousRoute=location.hash;window.addEventListener('hashchange',()=>{if($('#portal-dialog').open)closeModal();if(location.hash==='#pos'&&previousRoute!=='#pos'){state.network='Ethereum';state.search=''}previousRoute=location.hash;render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})});render();
// Theme and language preferences are stored locally; account data is not persisted here.
const themeMedia=matchMedia('(prefers-color-scheme: dark)');
let explicitTheme=false;
try {explicitTheme=['light','dark'].includes(localStorage.getItem('orbs-portal-theme'));} catch {}
function updateThemeLabel(){const dark=document.documentElement.dataset.theme==='dark';const label=dark?t("Switch to light mode"):t("Switch to dark mode");$('#theme-toggle').setAttribute('aria-label',label);$('#theme-toggle').title=label;}
$('#theme-toggle').addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;explicitTheme=true;try{localStorage.setItem('orbs-portal-theme',next)}catch{}updateThemeLabel()});
themeMedia.addEventListener('change',e=>{if(!explicitTheme){document.documentElement.dataset.theme=e.matches?'dark':'light';updateThemeLabel()}});
window.addEventListener('storage',e=>{if(e.key==='orbs-portal-theme'){explicitTheme=['light','dark'].includes(e.newValue);document.documentElement.dataset.theme=explicitTheme?e.newValue:themeMedia.matches?'dark':'light';updateThemeLabel()}});
updateThemeLabel();

document.addEventListener('error',e=>{if(e.target.matches?.('.social-thumbnail img')){const a=e.target.closest('.social-thumbnail');if(a.dataset.socialKind==='announcements'&&!e.target.dataset.logoFallback){e.target.dataset.logoFallback='true';e.target.src='https://www.orbs.com/marketing/brand-assets/orbs-logo-vertical.svg';e.target.alt='Orbs logo';a.classList.add('social-logo-thumbnail');return;}a.classList.add('image-unavailable');a.textContent=t("View image in original post ↗");}},true);

loadWallet().catch(()=>{});

setInterval(()=>{if(state.connected&&location.hash==='#mypage'&&!document.hidden)accountPartNames.forEach(part=>{const p=accountParts[part];if(p?.data&&Date.now()-p.fetchedAt>=600000)loadAccountPart(part);});},30000);

function copyAddressButton(address){return `<button type="button" class="copy-address" data-copy-address="${escapeHTML(address)}" aria-label="${t('Copy address')}" title="${t('Copy address')}"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/></svg></button>`;}
let addressToastTimer;
function addressToast(key){document.querySelector('#address-toast')?.remove();clearTimeout(addressToastTimer);const toast=document.createElement('div');toast.id='address-toast';toast.className='address-toast';toast.setAttribute('role','status');toast.setAttribute('aria-live','polite');toast.textContent=t(key);const dialog=document.querySelector('#portal-dialog');(dialog.open?document.querySelector('#dialog-content'):document.body).append(toast);addressToastTimer=setTimeout(()=>toast.remove(),3000);}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-copy-address]');if(!button)return;const address=button.dataset.copyAddress;if(!/^0x[0-9a-f]{40}$/i.test(address))return;try{await navigator.clipboard.writeText(address);addressToast('Address copied to clipboard.');}catch{addressToast('Unable to copy. Please copy the address manually.');}});

// Fit addresses to their actual available width, retaining both ends only when needed.
function fitGuardianAddress(el){const full=el.dataset.fullAddress;el.textContent=full;if(el.scrollWidth<=el.clientWidth)return;let low=0,high=full.length-1,best='...';while(low<=high){const keep=Math.floor((low+high)/2),left=Math.ceil(keep/2),right=Math.floor(keep/2);const candidate=full.slice(0,left)+'...'+(right?full.slice(-right):'');el.textContent=candidate;if(el.scrollWidth<=el.clientWidth){best=candidate;low=keep+1;}else high=keep-1;}el.textContent=best;}
const guardianAddressObserver=new ResizeObserver(entries=>entries.forEach(({target})=>fitGuardianAddress(target)));
const observedGuardianAddresses=new Set();
function observeGuardianAddresses(){for(const el of observedGuardianAddresses)if(!el.isConnected){guardianAddressObserver.unobserve(el);observedGuardianAddresses.delete(el);}document.querySelectorAll('.guardian-address-text').forEach(el=>{if(!observedGuardianAddresses.has(el)){observedGuardianAddresses.add(el);guardianAddressObserver.observe(el);fitGuardianAddress(el);}});}
new MutationObserver(records=>{if(records.some(r=>[...r.addedNodes,...r.removedNodes].some(n=>n.nodeType===1)))observeGuardianAddresses();}).observe(document.querySelector('#main'),{childList:true,subtree:true});
observeGuardianAddresses();
document.fonts.ready.then(()=>observedGuardianAddresses.forEach(fitGuardianAddress));
document.fonts.addEventListener('loadingdone',()=>observedGuardianAddresses.forEach(fitGuardianAddress));
